serviceRoute(worker,target){const origin={x:Math.round(worker.x),y:Math.round(worker.y)};const starts=this.roads.has(key(origin.x,origin.y))?[key(origin.x,origin.y)]:this.nearRoads({...origin,type:this.at(origin.x,origin.y)?.type==='house'?'house':undefined}),goals=new Set(this.nearRoads(target));const q=starts.filter(k=>this.connected.has(k)),parents=new Map(q.map(k=>[k,null]));for(let i=0;i<q.length;i++){const k=q[i];if(goals.has(k)){const route=[];for(let p=k;p!==null;p=parents.get(p))route.push(p.split(',').map(Number));const road=route.reverse();worker.roadCells=road.map(([x,y])=>key(x,y));const from=this.at(origin.x,origin.y)?.type==='house'?this.houseAccessPath({...origin,type:'house'},road[0]):[[worker.x,worker.y],road[0]],to=target.type==='house'?this.houseAccessPath(target,road.at(-1)).reverse():[road.at(-1),[target.x,target.y]];return [...from,...road.slice(1,-1),...to];}const[x,y]=k.split(',').map(Number);for(const[dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const n=key(x+dx,y+dy);if(this.connected.has(n)&&!parents.has(n)){parents.set(n,k);q.push(n);}}}return [];}
