resourceAmount(good){return this.buildings.reduce((n,b)=>n+(b.stock?.[good]||0),0)+this.inTransit.reduce((n,s)=>n+(s.good===good?s.amount:0),0)+this.missions.reduce((n,m)=>n+(m.kind==='import'&&m.good===good?m.amount:0),0)+(good==='berries'?this.foragers.reduce((n,w)=>n+(w.cargo||0),0):good==='wood'?this.lumberjacks.reduce((n,w)=>n+(w.cargo||0),0):good==='game'?this.hunters.reduce((n,w)=>n+(w.cargo||0),0):good==='fish'?this.boats.reduce((n,w)=>n+(w.cargo||0),0):0);}
